import{_ as t,c as e,a2 as a,o as s}from"./chunks/framework.CqbvlPrP.js";const o="/assets/1.CCP390hP.webp",r="/assets/2.BQ8Q162j.webp",h=JSON.parse('{"title":"关于盘整的问题","description":"","frontmatter":{},"headers":[],"relativePath":"stock/缠论印证/天下无缠/关于盘整的问题.md","filePath":"stock/缠论印证/天下无缠/关于盘整的问题.md"}'),c={name:"stock/缠论印证/天下无缠/关于盘整的问题.md"};function n(_,p,i,l,d,m){return s(),e("div",null,p[0]||(p[0]=[a('<h1 id="关于盘整的问题" tabindex="-1">关于盘整的问题 <a class="header-anchor" href="#关于盘整的问题" aria-label="Permalink to &quot;关于盘整的问题&quot;">​</a></h1><p>想去西北旅游，有哪些游玩攻略分享？</p><p>孙北漠与唐南溪</p><p>关于盘整的问题，我个人习惯称震荡，实际上我在之前的文章里有提过，震荡究竟何时转单边，实际上是无法提前预知的，震荡的本质属性就是无序的在一个相对的空间内上下运动，中间产生的走势类型的级别也并不都是一定的对称的级别。</p><p>但是这件事还是可以拿出来，当作一个单元聊一聊。</p><p>实际上震荡是怎么转单边的，我们习惯上认为的是次一级别的延续造成的，也就是次级别朝一个方向运动，且级别不发生变化，脱离中枢区间，即单边形成，但是这个单边到底能走多远，这个依然是无法提前预知的。</p><p>我刚才说了，我们习惯上认为是次一级别，但实际上中，也可能是次次级别即次级别以下级别的走势类型朝一个方向不发生变化产生的单边，但你们知道为什么缠师说了一个次级别举例子，没往下说么？</p><p>这里牵扯到一个实际交易中的问题，比方说一个30级别的震荡，你看到一个1分的延续，就是次次级别，你做进去了，理论上你看到了震荡内部的小级别延续了，比方1分的趋势走势类型，你认为它可能走出30的震荡区域了，这本质上没什么问题，因为前面说了，单边离开震荡区域本质上就是次级别以下级别的延续么，但是这里你思考一个问题，比方方向是向上的，1分的第二个中枢形成后，你做进去了，结果他走了1分的下，你应该如何看待当下的情况呢？是离开震荡区间失败了吗？这里实际上不能这么看，1分两中枢后你做进去，出了1分的反向走势，它有没有可能是要做一个5分的中枢呢？然后由1趋势加1分下变成5，由这个5分，也就是30的震荡的次级别离开震荡区间，形成单边走势离开呢？</p><p>这里我个人想强调的一点是什么呢，确实是有次次级别的延续离开震荡区间走出单边的情况，但是如果你做进去，次次级别形成了次级别的震荡，你心理一定会觉得不舒服，因为你做进去它不涨啊，所以我理解缠师提出次级别的用意可能就在这，他不是否定次级别以下级别不能走出单边，而是取了一个临界值，即次级别，也就是你都次级别了，再不走出去，就有点不像话了，如果是次级别以下级别，就还是有缓一缓的余地，毕竟，我次次级别可以先不走出去，我再弄一个次级别走出去也无伤大雅。</p><p>这是我想讲的第一个点。</p><p>第二点是我想说什么呢，还是我之前的文章曾经提到过，所以我一直说，其实没什么好写的了，再写都是重复前面的点，也就是不要妄图去猜震荡何时转单边，因为猜不出来，比方我前面提到过争议最大就是，9个1分的走势类型重叠可不可以形成30分钟级别的中枢，我个人认知一直是可以的，还讲了君子不器皿，也是为了印证这个说法，就着这个我们先说三个1分走势类型重叠，理论上它肯定够5分级别了，实际上就是5分的震荡或者你叫盘整也可以，那么它就一定走出单边么？不一定啊，后面又走了6个1分的上下上，整体构成30分级别的震荡，然后走了30分的单边大幅上涨，不可以么？当然可以，不然就不会出现9个1分够30这种说法了。</p><p>上面是我想解决北游的第一个问题，也就是如何提前判断可能有效离开中枢的次级别的走势，严格一点说，有些办法是可以筛选出可能有效的次级别走出震荡区域，但是我想了想还是觉得如果告诉你，可能还是会误导你，因为一单你觉得哪里能会出现有效的离开，人就会不自觉的下重仓位，而忘记了，它仅仅是可能有效的离开，不用多，你成功个几次，一定会在之后的位置下个重仓位，走势一但没按照之前的走，你铁定亏的很惨，这是人性，也是规律。</p><p>其实震荡的具体操作办法，前面的文章实际上有写，先说一个主基调，单边的仓位究竟是怎么留下的？实际上都是在震荡里留下的，而不是突破以后做进去的。</p><p>比方你住在一个四合院，天不亮你就起床去上班了，天黑之前你就回到家睡觉了，这样即使你有邻居，理论上可能一辈子你们也可能见不到面。</p><p>市场实际上就是你的那个邻居，你要想办法不让它发现你，但是你就在它隔壁住着，虽不产生交集，却形影不离。</p><p>震荡和单边也类似这样的关系，震荡中，你看到次级别的完整走势类型，看着它差不多走完了，你进去就完了，它横着走，也就走，它成功反向了，反向结束了你也走，留下一点仓位就好了，如果它震荡的够长，你的仓位就会越多，当单边走出来的时候，你的利润就会越高，也就是震荡的时候才该去想单边的事情，反过来，当单边出现，你该想的问题是怎么减仓的问题，因为震荡不会一直震，单边必然不可能一直涨，所以当所有人都发现单边出现买入的时候，你实际上是在默默的出掉你的仓位，这就是节奏啊，而中间的参照物或者尺子就是级别，多大级别的震荡，里面的次级别是多大级别的完整走势类型，心中要有数，不要想着它会一下子涨到天上去，基本不可能，有也是少数情况，那种次次级别直接拉的回不来的，基本很少见，即使拉上去，大多也要做一个次级别的震荡后才会接着上去。</p><p>关于北游的第二个问题，我画一个图，对这个图，我做一个简单的说明之后，大家都想想，虽然看起来跟三买没什么关系，但有没有关系自己琢磨琢磨。</p><p><img src="'+o+'" alt="图片"></p><p>红色和绿色的两个图，所有中枢级别都是一样的。</p><p>缠师说没有趋势就没有背驰，红色的图，是两个中枢，向下，趋势走势类型下跌，绿色的图，一个中枢，向下，盘整走势类型下。</p><p>现在我把红色图最后那个中枢后破的那个低点擦掉，两个图比较一下，是否有区别？</p><p><img src="'+r+'" alt="图片"></p><p>或者我换一个问法，第二个下跌中枢破了低点以后直接向上拉起来了，那么我问一句，这个破位的低点我能不能忽略不计？</p><p>如果这样画，他就不是趋势走势类型了，变成了绿色的那个图，但是确实两个图后面都拉起来了，那么还是那个问题，红色第二中枢的那个低点我能该怎么看待它？</p><p>我再换一个问法，那个绿色的图，明明没有两中枢背驰，就是一个一中枢的盘整走势类型下跌，它为什么能拉起来？</p><p>我再换一个描述，那个绿色的图之后拉起来了，我能不能假定下面起来的绿色上涨中枢是最后一个下跌中枢呢？也就是绿色下面的那个中枢我假定它是破了低点之后才起来的，这样我就凑够了绿色两中枢趋势走势类型下跌，所以绿色的也涨起来了呢？</p><p>何为君子不器？北游？</p>',27)]))}const u=t(c,[["render",n]]);export{h as __pageData,u as default};
